import React, { useEffect } from 'react';
import useHotelStore from '../store/useHotelStore';
import useProfileStore from '../store/useProfileStore'; // <-- Импортируем новый стор
import { Card } from '../components/ui/Card';
import { Badge } from '../components/ui/Badge';
import { Camera, Thermometer, ChevronLeft, ChevronRight, Settings2, ShieldCheck, FileSignature, AlertTriangle, X, Building2, TrendingUp, Lock } from 'lucide-react';
import { cn } from '../components/ui/Card';

const DAYS = Array.from({ length: 15 }, (_, i) => i + 8); // 8th to 22nd

const getStatusColors = (status, source) => {
  if (source === 'ozon') return 'bg-ozon-50 border-ozon-300 text-ozon-900 shadow-sm';
  switch (status) {
    case 'checked-in': return 'bg-green-100 border-green-300 text-green-800';
    case 'pending': return 'bg-orange-100 border-orange-300 text-orange-800';
    default: return 'bg-gray-100 border-gray-300 text-gray-800';
  }
};

const HotelPage = () => {
    const { bookings, occupancyRate, isLoading, loadData, selectedBooking, setSelectedBooking } = useHotelStore();
    const { activeModules, toggleModule } = useProfileStore();

  useEffect(() => {
    loadData();
  },[loadData]);
  if (!activeModules.hotel) {
    return (
        <div className="flex flex-col items-center justify-center h-[calc(100vh-8rem)] max-w-2xl mx-auto text-center animate-in fade-in zoom-in-95 duration-500">
          <div className="w-24 h-24 bg-brand-50 text-brand-600 rounded-full flex items-center justify-center mb-6 shadow-sm border border-brand-100">
            <Building2 size={48} />
          </div>
          <h2 className="text-3xl font-bold text-gray-900 tracking-tight mb-3">
            Модуль «Зоогостиница» отключен
          </h2>
          <p className="text-gray-500 mb-8 leading-relaxed">
            У вас есть вольеры или вы берете животных на передержку? Включите этот модуль, чтобы получить бесплатную CRM (шахматку) для управления номерами и доступ к миллионам клиентов Ozon.
          </p>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-4 w-full mb-8 text-left">
            <Card className="bg-white border-gray-200">
              <TrendingUp className="text-brand-500 mb-2" size={24} />
              <h4 className="font-bold text-gray-900 text-sm mb-1">Поток клиентов</h4>
              <p className="text-xs text-gray-500">Заполним ваши вольеры в "мертвый" сезон за счет трафика с Ozon Travel.</p>
            </Card>
            <Card className="bg-white border-gray-200">
              <Lock className="text-ozon-500 mb-2" size={24} />
              <h4 className="font-bold text-gray-900 text-sm mb-1">Защита от отмен</h4>
              <p className="text-xs text-gray-500">Холдирование средств и 100% компенсация штрафов при неявке клиента.</p>
            </Card>
          </div>

          <button
              onClick={() => toggleModule('hotel')}
              className="bg-brand-600 hover:bg-brand-700 text-white px-8 py-3.5 rounded-xl font-bold shadow-lg transition-all hover:scale-105"
          >
            Активировать бесплатно
          </button>
        </div>
    );
  }

  const rooms =[
    { id: 'vip_1', name: 'Вольер VIP #1', hasCamera: true, hasClimate: true },
    { id: 'std_1', name: 'Стандарт #1', hasCamera: false, hasClimate: false },
    { id: 'std_2', name: 'Стандарт #2', hasCamera: false, hasClimate: false },
    { id: 'cat_1', name: 'Кошачий блок А', hasCamera: true, hasClimate: false },
  ];

  if (isLoading) {
    return (
        <div className="animate-pulse flex flex-col gap-4">
          <div className="h-8 w-64 bg-gray-200 rounded"></div>
          <div className="h-[600px] w-full bg-gray-200 rounded-2xl"></div>
        </div>
    );
  }

  return (
      <div className="flex h-[calc(100vh-8rem)] relative overflow-hidden">

        {/* Main Content */}
        <div className={cn(
            "flex-1 flex flex-col transition-all duration-300",
            selectedBooking ? "pr-[400px]" : ""
        )}>
          <div className="flex items-center justify-between mb-4 flex-shrink-0">
            <div>
              <h2 className="text-xl font-bold tracking-tight text-gray-900">Управление номерным фондом</h2>
              <div className="text-sm text-gray-500 flex items-center gap-2 mt-1">
                Загрузка номеров (Май):
                <div className="w-48 h-2 bg-gray-200 rounded-full overflow-hidden">
                  <div className="h-full bg-brand-500 rounded-full" style={{ width: `${occupancyRate}%` }}></div>
                </div>
                <span className="font-semibold text-gray-700">{occupancyRate}%</span>
              </div>
            </div>

            <div className="flex items-center gap-3">
              <div className="flex items-center bg-white border border-gray-200 rounded-xl p-1 shadow-sm">
                <button className="p-1.5 hover:bg-gray-50 rounded-lg text-gray-500"><ChevronLeft size={18} /></button>
                <div className="px-3 py-1 font-medium text-sm text-gray-800">Май 2026</div>
                <button className="p-1.5 hover:bg-gray-50 rounded-lg text-gray-500"><ChevronRight size={18} /></button>
              </div>
              <button className="p-2 border border-gray-200 bg-white rounded-xl hover:bg-gray-50 shadow-sm text-gray-500">
                <Settings2 size={18} />
              </button>
            </div>
          </div>

          <Card className="flex-1 overflow-hidden p-0 rounded-2xl flex flex-col">
            {/* Table Header */}
            <div className="flex border-b border-gray-200 bg-gray-50 relative z-10 flex-shrink-0">
              <div className="w-64 border-r border-gray-200 p-4 font-semibold text-sm text-gray-700 flex-shrink-0 flex items-center bg-white shadow-[2px_0_5px_rgba(0,0,0,0.02)] z-20">
                Номер / Вольер
              </div>
              <div className="flex-1 flex overflow-hidden">
                {DAYS.map(day => (
                    <div key={day} className={cn(
                        "flex-1 min-w-[80px] p-2 text-center text-sm border-r border-gray-200 border-dashed",
                        [9, 10, 16, 17].includes(day) ? "bg-gray-100 text-gray-500 font-medium" : "text-gray-900 font-semibold"
                    )}>
                      {day} <span className="block text-[10px] text-gray-400 font-normal">мая</span>
                    </div>
                ))}
              </div>
            </div>

            {/* Gantt Body */}
            <div className="flex-1 overflow-y-auto overflow-x-hidden relative">
              {rooms.map(room => (
                  <div key={room.id} className="flex border-b border-gray-100 h-20 group hover:bg-gray-50/50 transition-colors">

                    {/* Left Column */}
                    <div className="w-64 border-r border-gray-200 p-4 flex-shrink-0 flex items-center justify-between bg-white group-hover:bg-gray-50/50 transition-colors z-20 relative">
                      <span className="font-medium text-sm text-gray-900">{room.name}</span>
                      <div className="flex gap-1.5 text-gray-400">
                        {room.hasCamera && <Camera size={14} className="text-blue-500" />}
                        {room.hasClimate && <Thermometer size={14} className="text-orange-500" />}
                      </div>
                    </div>

                    {/* Days Grid & Bars */}
                    <div className="flex-1 flex relative">
                      {DAYS.map(day => (
                          <div key={day} className={cn("flex-1 min-w-[80px] border-r border-gray-200 border-dashed",[9, 10, 16, 17].includes(day) && "bg-gray-50")} />
                      ))}

                      {/* Render Bookings */}
                      {bookings.filter(b => b.roomId === room.id).map(booking => {
                        const checkInIdx = DAYS.indexOf(Number(booking.checkIn));
                        const checkOutIdx = DAYS.indexOf(Number(booking.checkOut));
                        if (checkInIdx === -1 || checkOutIdx === -1) return null;

                        const leftPercent = (checkInIdx / DAYS.length) * 100;
                        const widthPercent = ((checkOutIdx - checkInIdx) / DAYS.length) * 100;

                        return (
                            <div
                                key={booking.id}
                                onClick={() => setSelectedBooking(booking)}
                                className={cn(
                                    "absolute top-2 bottom-2 rounded-xl border p-2 shadow-sm text-xs cursor-pointer hover:shadow-md transition-all overflow-hidden flex flex-col justify-center",
                                    getStatusColors(booking.status, booking.source)
                                )}
                                style={{ left: `calc(${leftPercent}% + 4px)`, width: `calc(${widthPercent}% - 8px)` }}
                            >
                              <div className="flex items-center gap-1">
                                {booking.source === 'ozon' && <ShieldCheck size={12} className="text-ozon-600" />}
                                <span className="font-bold truncate">{booking.petName}</span>
                              </div>
                              <div className="text-[10px] opacity-80 truncate mt-0.5">
                                {booking.source === 'ozon' ? 'Сделка защищена Ozon' : 'Прямая бронь'}
                              </div>
                            </div>
                        );
                      })}
                    </div>
                  </div>
              ))}
            </div>
          </Card>
        </div>

        {/* Booking Details Drawer (Legal & Financials) */}
        <div className={cn(
            "absolute top-0 right-0 bottom-0 w-[400px] bg-white border-l border-gray-200 shadow-2xl transition-transform duration-300 ease-in-out flex flex-col z-20",
            selectedBooking ? "translate-x-0" : "translate-x-full"
        )}>
          {selectedBooking && (
              <>
                <div className="px-6 py-4 border-b border-gray-100 flex items-center justify-between bg-gray-50/50">
                  <span className="font-bold text-gray-900">Детали бронирования</span>
                  <button onClick={() => setSelectedBooking(null)} className="p-1.5 hover:bg-gray-200 rounded-lg text-gray-500 transition-colors">
                    <X size={18} />
                  </button>
                </div>

                <div className="flex-1 overflow-y-auto p-6 hide-scrollbar space-y-6">

                  {/* Guest Info */}
                  <div>
                    <h2 className="text-2xl font-bold text-gray-900">{selectedBooking.petName}</h2>
                    <p className="text-sm text-gray-500 mt-1">{selectedBooking.checkIn} — {selectedBooking.checkOut} мая (5 суток)</p>
                    <div className="mt-3">
                      {selectedBooking.source === 'ozon'
                          ? <Badge icon="ozon" variant="ozon">Заказ через Ozon PetCare</Badge>
                          : <Badge variant="default">Создано вручную (Direct)</Badge>}
                    </div>
                  </div>

                  {/* Legal & Financial Shield Block (Crucial for B2B arguments) */}
                  <div className="space-y-3">
                    <h3 className="text-sm font-bold text-gray-900 uppercase tracking-wider">Юридическая и фин. защита</h3>

                    {selectedBooking.financials.guarantee ? (
                        <div className="bg-green-50 border border-green-200 rounded-xl p-4 flex gap-3">
                          <ShieldCheck className="text-green-600 flex-shrink-0 mt-0.5" size={20} />
                          <div>
                            <p className="font-semibold text-sm text-green-900 mb-1">Безопасная сделка активна</p>
                            <p className="text-xs text-green-800">
                              Сумма <b>{selectedBooking.financials.total} ₽</b> захолдирована Ozon Pay. В случае неявки клиента (No-show) гостиница гарантированно получит компенсацию 100% за первые сутки.
                            </p>
                          </div>
                        </div>
                    ) : (
                        <div className="bg-orange-50 border border-orange-200 rounded-xl p-4 flex gap-3">
                          <AlertTriangle className="text-orange-600 flex-shrink-0 mt-0.5" size={20} />
                          <div>
                            <p className="font-semibold text-sm text-orange-900 mb-1">Прямая бронь (Без гарантий)</p>
                            <p className="text-xs text-orange-800">Оплата на месте. В случае отмены платформа не сможет компенсировать простой вольера.</p>
                          </div>
                        </div>
                    )}

                    {selectedBooking.legal.contractSigned ? (
                        <div className="bg-blue-50 border border-blue-200 rounded-xl p-4 flex gap-3">
                          <FileSignature className="text-blue-600 flex-shrink-0 mt-0.5" size={20} />
                          <div>
                            <p className="font-semibold text-sm text-blue-900 mb-1">Договор подписан ПЭП</p>
                            <p className="text-xs text-blue-800">
                              Клиент подтвердил отказ от претензий через Ozon ID. Электронный акт приема-передачи сформирован и имеет юридическую силу.
                            </p>
                          </div>
                        </div>
                    ) : (
                        <div className="bg-gray-50 border border-gray-200 rounded-xl p-4 flex gap-3">
                          <FileSignature className="text-gray-400 flex-shrink-0 mt-0.5" size={20} />
                          <div>
                            <p className="font-semibold text-sm text-gray-700 mb-1">Бумажный документооборот</p>
                            <p className="text-xs text-gray-500">Не забудьте распечатать и подписать договор физически при заезде клиента.</p>
                          </div>
                        </div>
                    )}
                  </div>

                  {/* Owner Info */}
                  <div>
                    <h3 className="text-sm font-bold text-gray-900 uppercase tracking-wider mb-3">Контакты</h3>
                    <div className="bg-gray-50 rounded-xl p-4 border border-gray-100">
                      <p className="text-sm text-gray-600">{selectedBooking.ownerPhone}</p>
                    </div>
                  </div>
                </div>

                <div className="p-4 border-t border-gray-100 bg-white space-y-2">
                  <button className="w-full bg-gray-900 hover:bg-black text-white py-3 rounded-xl text-sm font-semibold transition-colors shadow-sm">
                    Редактировать карточку
                  </button>
                </div>
              </>
          )}
        </div>

      </div>
  );
};

export default HotelPage;