import { create } from 'zustand';

const useProfileStore = create((set) => ({
    // По умолчанию включим базовые вещи, а Гостиницу и Биржу сделаем неактивными для демонстрации
    activeModules: {
        dashboard: true,
        schedule: true,   // Расписание и ЕМИАС
        hotel: false,     // Зоогостиница (ВЫКЛЮЧЕНА)
        gigs: false,      // Биржа заявок (ВЫКЛЮЧЕНА)
        market: true,     // Маркет (включен)
        clients: true,    // CRM
        sos: true,        // Телемед
        finance: true     // Финансы
    },

    toggleModule: (moduleId) => set((state) => ({
        activeModules: {
            ...state.activeModules,
            [moduleId]: !state.activeModules[moduleId]
        }
    }))
}));

export default useProfileStore;